(function(root){const copy=s=>structuredClone(s);function entry(s,account,delta,type,ref){const next=(s.balances[account]||0)+delta;if(!Number.isSafeInteger(next)||next<0)throw Error('余额不足');s.balances[account]=next;s.entries.unshift({account,delta,type,ref,balance:next,time:new Date().toLocaleString('zh-CN')});}const W={empty:()=>({balances:{buyer:0},holds:{},paid:[],entries:[],keys:[]}),amount(value){if(!/^\d+(\.\d{1,2})?$/.test(value))throw Error('金额须为正数，最多两位小数');const cents=Math.round(Number(value)*100);if(!Number.isSafeInteger(cents)||cents<=0||cents>100000)throw Error('单次充值须大于 0 且不超过 1,000');return cents;},credit(state,account,cents,type,key){if(!Number.isSafeInteger(cents)||cents<=0||cents>100000)throw Error('充值金额无效');if(state.keys.includes(key))return state;const s=copy(state);entry(s,account,cents,type,key);s.keys.push(key);return s;},pay(state,orders){if(!orders.length)throw Error('没有待付款订单');const s=copy(state);for(const o of orders){if(s.paid.includes(o.id)||!Number.isSafeInteger(o.totalCents)||o.totalCents<=0)throw Error('订单已付款或金额无效');entry(s,'buyer',-o.totalCents,'购物扣款',o.id);s.holds[o.id]={amount:o.totalCents,seller:o.shop===0?'buyer':'seller:'+o.shop};s.paid.push(o.id);}return s;},release(state,id,refund){const hold=state.holds[id];if(!hold)throw Error('订单没有待结算资金，不能重复处理');const s=copy(state);entry(s,refund?'buyer':hold.seller,hold.amount,refund?'退款到账':'经营收入',id);delete s.holds[id];return s;}};if(typeof module!=='undefined')module.exports=W;else root.WalletModel=W;})(globalThis);
